contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint dep, uint am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (dep)); require(dep <= 1000000000000000000000000000000);
        require(dep >= 1 ether);
        require(am <= dep);

        c.Deposit{value: dep}(); if (__ESBMC_reverted()) return;

        uint beforeBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cBefore = address(c).balance;
        uint selfBefore = address(this).balance;

        bool reverted;
        c.Collect(am); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint afterBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cAfter = address(c).balance;
        uint selfAfter = address(this).balance;

        assert(!reverted && afterBal == beforeBal - am && cAfter == cBefore - am && selfAfter == selfBefore + am);
    }
}

