pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 dep, uint256 am) internal {
        dep = bound(dep, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(dep >= 1 ether);
        vm.assume(am <= dep);
        try c.Deposit{value: dep}() {} catch { return; }
        uint256 beforeBal;
        try c.balances(address(this)) returns (uint256 __r) { beforeBal = __r; } catch { return; }
        uint cBefore = address(c).balance;
        uint selfBefore = address(this).balance;
        bool reverted;
        try c.Collect(am) { reverted = false; } catch { reverted = true; }
        uint256 afterBal;
        try c.balances(address(this)) returns (uint256 __r) { afterBal = __r; } catch { return; }
        uint cAfter = address(c).balance;
        uint selfAfter = address(this).balance;
        assertTrue(!reverted && afterBal == beforeBal - am && cAfter == cBefore - am && selfAfter == selfBefore + am);
    }

    function testFuzz_run(uint256 dep, uint256 am) public {
        _run(dep, am);
    }

    receive() external payable {}
}
